  await backend.route("**/api/search?*", (route) => route.fulfill({ json: {
    entities: [{ id: "10000000-0000-0000-0000-000000000009", name: "Unite", kind: "Funder", funder_kind: "Trade Union", match_source: null }],
  } }));
  await page.goto("/search?q=West");
  await expect(page.getByRole("alert")).toContainText("unexpected match source");
  await expect(page.locator(".entity-row")).toHaveCount(0);
});
EOF
cat >> frontend/tests/entity-details.spec.ts <<'EOF'

test("malformed details show an error and recover after retry", async ({ backend, page }) => {
  let calls = 0;
  await backend.route("**/api/members/1", (route) => route.fulfill({ json: ++calls === 1 ? { ...memberDetails, member: { ...member, id: "2" } } : memberDetails }));
  await page.goto("/members/1");
  await expect(page.getByRole("alert")).toContainText("unexpected response");
  await page.getByRole("button", { name: "Try again" }).click();
  await expect(page.getByRole("heading", { name: member.name, exact: true })).toBeVisible();
});
EOF
